package com.br.edu.iff.rachaconta.webproject.controller;
import com.br.edu.iff.rachaconta.webproject.service.*;import org.springframework.stereotype.Controller;import org.springframework.ui.Model;import org.springframework.web.bind.annotation.*;
@Controller @RequestMapping("/dividas") public class DividasController{private final DividaService s;private final RelatorioFinanceiroService rel;public DividasController(DividaService s,RelatorioFinanceiroService r){this.s=s;rel=r;}@GetMapping public String lista(Model m){m.addAttribute("dividas",s.listar());m.addAttribute("nome",(java.util.function.Function<Long,String>)rel::nome);return "dividas/lista";}@PostMapping("/{id}/pagar")public String pagar(@PathVariable Long id){s.marcarComoPaga(id);return "redirect:/dividas";}@PostMapping("/{id}/excluir")public String excluir(@PathVariable Long id){s.excluir(id);return "redirect:/dividas";}}
